import java.util.*; abstract class Room08{double u;int people;Room08(double u,int p){this.u=Math.max(0,u);people=Math.max(1,p);}abstract double bill();} class Single08 extends Room08{Single08(double u,int p){super(u,p);}double bill(){return u*8;}} class Shared08 extends Room08{Shared08(double u,int p){super(u,p);}double bill(){return u*6/people;}} class AC08 extends Room08{AC08(double u,int p){super(u,p);}double bill(){return u*10+200;}} public class Week08Problem03{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double u=s.nextDouble();int p=s.nextInt();Room08 r=t.equals("SINGLE")?new Single08(u,p):t.equals("SHARED")?new Shared08(u,p):new AC08(u,p);System.out.printf("%s bill: %.2f%n",t,r.bill());total+=r.bill();}System.out.printf("Total: %.2f%n",total);}}